import{_ as i,a0 as d,w as r,s,ao as p,I as e,x as t,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const G=JSON.parse('{"title":"安卓编年史（23）：Android 4.3，果冻豆——早早支持可穿戴设备 | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史（23）：Android 4.3，果冻豆——早早支持可穿戴设备 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史（23）：Android 4.3，果冻豆——早早支持可穿戴设备 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史（23）：Android 4.3，果冻豆——早早支持可穿戴设备 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/24 - The history of Android","title":"安卓编年史（23）：Android 4.3，果冻豆——早早支持可穿戴设备","tag":"The history of Android","desc":""},"relativePath":"The history of Android/24 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/24 - The history of Android.md"};function g(u,o,A,f,y,T){const a=d("Link");return r(),s("div",null,[o[20]||(o[20]=p('<h1 id="安卓编年史-23-android-4-3-果冻豆——早早支持可穿戴设备" tabindex="-1">安卓编年史（23）：Android 4.3，果冻豆——早早支持可穿戴设备 <a class="header-anchor" href="#安卓编年史-23-android-4-3-果冻豆——早早支持可穿戴设备" aria-label="Permalink to “安卓编年史（23）：Android 4.3，果冻豆——早早支持可穿戴设备”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/Goooogleplaymusic.jpg" alt="漂亮的新 Google Play Music 应用，从电子风格转向完美契合 Play 商店的风格。"></p><p><em>漂亮的新 Google Play Music 应用，从电子风格转向完美契合 Play 商店的风格。 [Ron Amadeo 供图]</em></p><p>在 I/O 大会推出的另一个应用更新是 Google Music 应用。音乐应用经过了完全的重新设计，最终摆脱了蜂巢中引入的蓝底蓝色调的设计。Play Music 的设计和几个月前发布的 Play 商店一致，有着响应式的白色卡片布局。Music 同时还是最早采用新抽屉导航样式的主要应用之一。谷歌还随新应用发布了 Google Play Music All Access，每月 10 美元的包月音乐订阅服务。Google Music 现在拥有订阅计划，音乐购买，以及云端音乐存储空间。这个版本还引入了“Instant Mix”，谷歌会在云端给相似的歌曲计算出一份歌单。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/gooooogleplaygames.jpg" alt="一个展示对 Google Play Games 支持的游戏。上面是 Play 商店游戏特性描述，登陆游戏触发的权限对话框，Play Games 通知，以及成就界面。"></p><p><em>一个展示对 Google Play Games 支持的游戏。上面是 Play 商店游戏特性描述，登陆游戏触发的权限对话框，Play Games 通知，以及成就界面。 [Ron Amadeo 供图]</em></p><p>谷歌还引入了 “Google Play Games”，一个后端服务，开发者可以将其附加到游戏中。这项服务简单说就是安卓版的 Xbox Live 或苹果的 Game Center。开发者可以给游戏添加 Play Games 支持，这样就能通过使用谷歌的后端服务，更简单地将成就、多人游戏、游戏配对、用户账户以及云端存档集成到游戏中。</p><p>Play Games 是谷歌在游戏方面推进的开始。就像单独的 GPS 设备，翻盖手机，以及 MP3 播放器，智能手机的生产者希望游戏设备能够变成智能手机的一个功能点。当你有部智能手机的时候你为什么还有买个任天堂 DS 或 PS Vita 呢？一个易于使用的多人游戏服务是这项计划的重要部分，我们仍能看到这个决定最后的成果。在今天，坊间都在传言谷歌和苹果有关于客厅游戏设备的计划。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/goooglekeep.jpg" alt="Google Keep，谷歌自 Google Notebook 以来第一个笔记服务。"></p><p><em>Google Keep，谷歌自 Google Notebook 以来第一个笔记服务。 [Ron Amadeo 供图]</em></p>',10)),e("p",null,[o[1]||(o[1]=t("毫无疑问一些产品为了赶上 Google I/O 大会的发布准时开发完成了，",-1)),n(a,{href:"http://live.arstechnica.com/liveblog-google-io-2013-keynote/"},{default:l(()=>[...o[0]||(o[0]=[t("但是三个半小时内的主题",-1)])]),_:1}),o[2]||(o[2]=t("已经够多了，一些产品在大会的发布上忽略了。Google I/O 大会的三天后一切都清楚了，谷歌带来了 Google Keep，一个用于安卓和在线的笔记应用。Keep 看起来很简单，就是一个用上了响应式 Google-Now 风格设计的笔记应用。用户可以改变卡片的尺寸，从多栏布局改为单列视图。笔记可以由文本，清单，自动转文本的语音或者图片组成。笔记卡片可以拖动并在主界面重新组织，你甚至可以给笔记换个颜色。",-1))]),o[21]||(o[21]=p(`<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/05/gmail.png" alt="Gmail 4.5，换上了新的导航抽屉设计，去掉了几个按钮并将操作栏合并到了抽屉里。"></p><p><em>Gmail 4.5，换上了新的导航抽屉设计，去掉了几个按钮并将操作栏合并到了抽屉里。 [Ron Amadeo 供图]</em></p><p>在 I/O 大会之后，没有哪些应用没出现在谷歌的周期外更新里。2013 年 6 月，谷歌发布了新版设计的 Gmail。最显眼的变化就是一个月前 Google I/O 大会引入的新导航抽屉界面。最吸引眼球的变化是用上了 Google+ 资料图片来取代复选框。虽然复选框看起来被去掉了，它们其实还在那，点击邮件左边的图片就是了。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/newmaps11.png" alt="新谷歌地图，换上了全白的 Google-Now 风格主题。"></p><p><em>新谷歌地图，换上了全白的 Google-Now 风格主题。 [Ron Amadeo 供图]</em></p><p>一个月后，谷歌在 Play 商店发布了全新的谷歌地图。这是谷歌地图自冰淇淋三明治以来第一个经过细致地重新设计的版本。新版本完全适配了 Google Now 白色卡片审美，还大大减少了屏幕上显示的元素。新版谷歌地图似乎设计时有意使地图总是显示在屏幕上，你很难找到除了设置页面之外还能完全覆盖地图显示的选项。</p><p>这个版本的谷歌地图看起来活在它自己的小小设计世界中。白色的搜索栏“浮动”在地图之上，地图显示部分在它旁边和上面都有。这和传统的操作栏设计有所不同。一般在应用左上角的导航抽屉，在这里是在左下角。这里的主界面没有向上按钮、应用图标，也没有浮动按钮。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/newmaps21.png" alt="新谷歌地图轻量化了许多，在一屏内能够显示更多的信息。"></p><p><em>新谷歌地图轻量化了许多，在一屏内能够显示更多的信息。 [Ron Amadeo 供图]</em></p><p>左边的图片显示的是点击了搜索栏后的效果（带键盘，这里关闭了）。过去谷歌在空搜索栏下面显示一个空页面，但在地图中，谷歌利用这些空间链接到新的“本地”页面。搜索结果页显示一般信息的结果，比如餐馆、加油站，以及景点。在结果页的底部是个列表，显示你的搜索历史和手动缓存部分地图的选项。</p><p>右侧图片显示的是地点页面。上面地图 7.0 的截图里显示的地图不是略缩图，它是完整的地图视图。在新版的谷歌地图中，地点作为卡片浮动显示在主地图之上，地图重新居中显示该地点。向上滑动可以让卡片覆盖地图，向下滑动可以显示带有底部一小条结果的完整地图。如果该地点是搜索结果列表中的一个，左右滑动可以在结果之间切换。</p><p>地点页面重新设计以显示更有用的信息概览。在第一页，新版添加了重要信息，比如地图上的位置，点评得分，以及点评数目。因为这是个手机，所以软件内可以直接拨打电话，电话号码的显示被认为是毫无意义的，被去掉了。旧版地点显示到那里的距离，新版谷歌地图显示到那里的时间，基于交通状况和偏好的交通方式——一个更加实用的衡量方式。新版还在中间放了个分享按钮，这使得通过即时通讯或短信协调的时候更加方便。</p><h3 id="android-4-3-果冻豆——早早支持可穿戴设备" tabindex="-1">Android 4.3，果冻豆——早早支持可穿戴设备 <a class="header-anchor" href="#android-4-3-果冻豆——早早支持可穿戴设备" aria-label="Permalink to “Android 4.3，果冻豆——早早支持可穿戴设备”">​</a></h3><p>如果谷歌没有在安卓 4.3 和安卓 4.2 之间通过 Play 商店发布更新的话，安卓 4.3 会是个不可思议的更新。如果新版 Play 商店、Gmail、地图、书籍、音乐、Hangouts 环聊，以及 Play Games 打包作为新版安卓的一部分，它将会作为有史以来最大的发布受到欢呼。虽然谷歌没必要延后新功能的发布。有了 Play 服务框架，只剩很少的部分需要系统更新，2013 年 7 月底谷歌发布了看似无关紧要的“安卓 4.3”。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/2014-03-28-12.231.jpg" alt="安卓 4.3 通知访问权限界面的可穿戴设备选项。
"></p><p><em>安卓 4.3 通知访问权限界面的可穿戴设备选项。 [Ron Amadeo 供图]</em></p><p>谷歌也毫无疑问地认为 4.3 的重要性不高，将新版也叫做“果冻豆”（第三个叫果冻豆的版本了）。安卓 4.3 的新功能列表像是谷歌无法通过 Play 商店或谷歌 Play 服务更新的部分的细目清单，大部分包含了为开发者作出的底层架构改动。</p><p>但许多新增功能似乎只为了一个目的——安卓 4.3 是谷歌对可穿戴计算支持的特洛伊木马。4.3 加入了低功耗蓝牙支持，使用很少的能耗将安卓和其它设备连接到一起并传输数据——可穿戴设备的必要特性。安卓 4.3 还添加了“通知访问权限”API，允许应用完全复制和控制通知面板。应用可以显示通知文本以及和用户操作一样地和通知交互——也就是点击操作按钮和消除通知。当你有个通知面板时从本机应用做这个操作没什么意义，但是在一个独立于你手机的设备上，复制通知面板的消息就显得很有用了。为数不多的接入的应用是 “Android Wear Preview（安卓可穿戴预览）”，使用了通知 API 驱动大部分的 Android Wear 界面。</p>`,18)),e("p",null,[o[4]||(o[4]=t("“4.3 是给可穿戴设备准备的”这个理论解释了 4.3 相对较少的新特性：它的推出是为了给 OEM 厂商时间去升级设备，为 ",-1)),n(a,{href:"http://arstechnica.com/gadgets/2014/03/in-depth-with-android-wear-googles-quantum-leap-of-a-smartwatch-os/"},{default:l(()=>[...o[3]||(o[3]=[t("Android Wear",-1)])]),_:1}),o[5]||(o[5]=t(" 的发布做准备。这个计划看起来起作用了。Android Wear 要求 安卓 4.3 及以上版本，安卓 4.3 已经发布很长时间了，大部分主要的旗舰设备都已经升级了。",-1))]),o[22]||(o[22]=e("p",null,"安卓并没有那么激动人心，但安卓从现在起的新版也不需要那么激动人心了。一切都变得那么模块化了，谷歌可以通过 Google Play 在它们完成时随时推送更新，不用再作为一个大系统更新来更新这么多组件。",-1)),o[23]||(o[23]=e("hr",null,null,-1)),o[24]||(o[24]=e("p",null,[e("img",{src:"http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg",alt:"Ron Amadeo"})],-1)),e("p",null,[n(a,{href:"http://arstechnica.com/author/ronamadeo"},{default:l(()=>[...o[6]||(o[6]=[t("Ron Amadeo",-1)])]),_:1}),o[8]||(o[8]=t(" / Ron是Ars Technica的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1)),n(a,{href:"https://twitter.com/RonAmadeo"},{default:l(()=>[...o[7]||(o[7]=[t("@RonAmadeo",-1)])]),_:1})]),o[25]||(o[25]=e("hr",null,null,-1)),e("p",null,[o[10]||(o[10]=t("via: ",-1)),n(a,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/24/"},{default:l(()=>[...o[9]||(o[9]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/24/",-1)])]),_:1})]),e("p",null,[o[13]||(o[13]=t("译者：",-1)),n(a,{href:"https://github.com/alim0x"},{default:l(()=>[...o[11]||(o[11]=[t("alim0x",-1)])]),_:1}),o[14]||(o[14]=t(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...o[12]||(o[12]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[17]||(o[17]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[15]||(o[15]=[t("LCTT",-1)])]),_:1}),o[18]||(o[18]=t(" 原创翻译，",-1)),n(a,{href:"http://linux.cn/"},{default:l(()=>[...o[16]||(o[16]=[t("Linux中国",-1)])]),_:1}),o[19]||(o[19]=t(" 荣誉推出",-1))])])}const w=i(m,[["render",g]]);export{G as __pageData,w as default};
